@sync_group.command("rm")
@click.argument("target")
def sync_rm(target: str):
    """Delete a document or folder from your clipboard.

    \b
    Examples:
        paperclip sync rm my_papers                    # delete folder
        paperclip sync rm usr_c1f9c5eac891             # delete single doc by ID
        paperclip sync rm --all                        # delete everything
    """
    from .. import config as _cfg
    cfg_data = _load_config()
    base_url = cfg_data.get("base_url", "https://paperclip.gxl.ai")

    headers: dict = {}
    api_key = os.environ.get("PAPERCLIP_API_KEY", "")
    if api_key:
        headers["X-API-Key"] = api_key
    else:
        from ..client.credentials import Credentials
        creds = Credentials.load()
        if creds:
            headers["Authorization"] = f"Bearer {creds.get_id_token()}"
        else:
            click.echo("Not authenticated. Run: paperclip login", err=True)
            raise SystemExit(1)

    if target == "--all":
        if not click.confirm("Delete ALL documents in your clipboard?"):
            return
        # Delete all folders by getting the tree first
        resp = requests.get(f"{base_url}/api/user/tree?path=", headers=headers, timeout=30)
        if resp.status_code != 200:
            click.echo(f"✗ Failed to list clipboard: {resp.status_code}")
            return
        tree = resp.json()
        # Delete each folder
        for folder in tree.get("folders", []):
            requests.delete(f"{base_url}/api/user/folders/{folder['name']}", headers=headers, timeout=30)
        # Delete root-level docs
        for doc in tree.get("documents", []):
            requests.delete(f"{base_url}/api/user/documents/{doc['id']}", headers=headers, timeout=30)
        click.echo("✓ Clipboard cleared")
        return

    # Try as folder first
    resp = requests.delete(f"{base_url}/api/user/folders/{target}", headers=headers, timeout=30)
    if resp.status_code == 200:
        data = resp.json()
        click.echo(f"✓ Deleted folder '{target}' ({data.get('deleted_count', '?')} docs)")
        return

    # Try as document ID
    doc_id = target
    if target.startswith("usr_"):
        doc_id = target  # the backend resolves usr_ IDs
    resp = requests.delete(f"{base_url}/api/user/documents/{doc_id}", headers=headers, timeout=30)
    if resp.status_code == 200:
        click.echo(f"✓ Deleted {target}")
    elif resp.status_code == 404:
        click.echo(f"✗ Not found: {target}")
    else:
        click.echo(f"✗ Delete failed: {resp.status_code}")


@click.command("upload")
@click.argument("files", nargs=-1, required=True,
                type=click.Path(exists=True, resolve_path=True, dir_okay=False))
@click.option("--into", "folder", default="",
              help="Destination clipboard folder, e.g. analyses/<slug>")
def upload_command(files: tuple, folder: str):
    """Upload generated file(s) into your paperclip clipboard.

    \b
    Examples:
        paperclip upload analysis.json --into analyses/my-topic
        paperclip upload index.html render_qa.json --into analyses/my-topic

    Persists analysis artifacts and reports (JSON/HTML/CSV/MD/PDF) to
    /clipboard/<folder>/. This is how you save generated files — the repo
    (`git`/`repo commit`) only stores the corpus + verified claims, NOT files.
    """
    import mimetypes

    folder = (folder or "").strip("/").replace("clipboard/", "").replace("/clipboard", "")

    # Resolve base_url honoring PAPERCLIP_BASE_URL env (matches the rest of the
    # CLI); reading the config file alone would ignore staging/local overrides.
    base_url = config.get_base_url()

    # Auth — Credentials.get_id_token() auto-refreshes an expired token.
    headers: dict = {}
    api_key = os.environ.get("PAPERCLIP_API_KEY", "")
    if api_key:
        headers["X-API-Key"] = api_key
    else:
        from ..client.credentials import Credentials
        creds = Credentials.load()
        if creds:
            headers["Authorization"] = f"Bearer {creds.get_id_token()}"
        else:
            click.echo("Not authenticated. Run: paperclip login", err=True)
            raise SystemExit(1)

    total = len(files)
    success = 0
    failed: list[tuple] = []
    dest_label = f"/clipboard/{folder + '/' if folder else ''}"

    for fp in files:
        p = Path(fp)
        mime = mimetypes.guess_type(p.name)[0] or "application/octet-stream"
        result = upload_file(base_url, headers, p, folder, mime=mime)
        if result.get("status") in ("success", "duplicate"):
            success += 1
            stored = result.get("filename")
            renamed = f" (stored as '{stored}')" if stored and stored != p.name else ""
            click.echo(f"  ✓ {p.name} → {dest_label}{renamed}")
        else:
            msg = result.get("message", "unknown error")
            failed.append((p.name, msg))
            click.echo(f"  ✗ {p.name}: {msg}", err=True)

    click.echo("")
    if failed:
        click.echo(f"{success}/{total} uploaded, {len(failed)} failed", err=True)
        raise SystemExit(1)
    click.echo(f"✓ {success}/{total} uploaded to {dest_label}")
    if folder:
        click.echo(f"  paperclip ls /clipboard/{folder}/")


@click.command(
    "cp",
    context_settings=dict(
        ignore_unknown_options=True,
        allow_extra_args=True,
        help_option_names=[],
    ),
)
@click.argument("args", nargs=-1, type=click.UNPROCESSED)
def cp_command(args: tuple):
    """Copy files into your paperclip clipboard.

    \b
    Local files are uploaded; corpus/clipboard paths are linked server-side.
        paperclip cp ~/my_papers/            → uploads to /clipboard/my_papers/
        paperclip cp paper.pdf               → uploads to /clipboard/paper.pdf
        paperclip cp /papers/PMC123 /clipboard/oa/   → links a corpus paper
        paperclip cp /clipboard/usr_abc /clipboard/other/  → links an existing doc

    Uploaded originals stay on disk; duplicates are skipped automatically.
    """
    from pathlib import Path as _Path

    positionals = [a for a in args if not str(a).startswith("-")]
    source = positionals[0] if positionals else None

    # A local filesystem path (that exists) is uploaded; anything else
    # (/papers, /fda, /trials, /clipboard, corpus IDs) is a server-side link.
    local_path = None
    if source is not None:
        candidate = _Path(source).expanduser()
        if candidate.exists():
            local_path = str(candidate.resolve())

    if local_path is None:
        from .app import _execute_argv

        _execute_argv("cp", list(args))
        return

    dest = positionals[1] if len(positionals) > 1 else "/clipboard/"
    _cp_upload_local(local_path, dest)


def _cp_upload_local(source: str, dest: str):
    """Upload local files/directories into the remote clipboard."""
    from pathlib import Path as _Path
    from concurrent.futures import ThreadPoolExecutor, as_completed

    target = _Path(source)

    # Determine folder name
    if dest and dest != "/clipboard/":
        folder_name = dest.strip("/").replace("clipboard/", "").replace("/clipboard", "")
    elif target.is_dir():
        folder_name = target.name
    else:
        folder_name = ""

    # Collect files
    if target.is_file():
        pdfs = [target]
    else:
        pdfs = sorted(f for f in target.rglob("*") if f.is_file() and f.suffix and not any(p.startswith(".") for p in f.relative_to(target).parts))
        if not pdfs:
            click.echo(f"No files found in {target}")
            return

    click.echo(f"Copying {len(pdfs)} file{'s' if len(pdfs) != 1 else ''} → /clipboard/{folder_name + '/' if folder_name else ''}")

    # Auth — use Credentials.get_id_token() which auto-refreshes expired tokens
    cfg_data = _load_config()
    base_url = cfg_data.get("base_url", "https://paperclip.gxl.ai")
    headers: dict = {}
    api_key = os.environ.get("PAPERCLIP_API_KEY", "")
    if api_key:
        headers["X-API-Key"] = api_key
    else:
        from ..client.credentials import Credentials
        creds = Credentials.load()
        if creds:
            token = creds.get_id_token()
            headers["Authorization"] = f"Bearer {token}"
        else:
            click.echo("Not authenticated. Run: paperclip login", err=True)
            raise SystemExit(1)

    # Upload with progress
    total = len(pdfs)
    success = 0
    errors = 0
    failed_files: list[tuple] = []

    import threading as _threading

    _cp_gate = _threading.Semaphore(4)

    def _upload_one(pdf):
        with _cp_gate:
            rel = pdf.relative_to(target) if target.is_dir() else pdf
            parts = list(rel.parent.parts) if target.is_dir() else []
            upload_folder = "/".join([folder_name] + [p for p in parts if p != "."]) if folder_name else ""
            result = upload_file(base_url, headers, pdf, upload_folder)
            time.sleep(0.25)
            return rel, result

    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = {executor.submit(_upload_one, pdf): pdf for pdf in pdfs}
        for future in as_completed(futures):
            rel, result = future.result()
            if result.get("status") in ("success", "duplicate"):
                success += 1
                stored = result.get("filename")
                renamed = f" (stored as '{stored}')" if stored and stored != rel.name else ""
                click.echo(f"  ✓ [{success + errors}/{total}] {rel}{renamed}")
            else:
                errors += 1
                msg = result.get("message", "unknown error")
                failed_files.append((rel, msg))
                click.echo(f"  ✗ [{success + errors}/{total}] {rel}: {msg}")

    click.echo("")
    if errors == 0:
        click.echo(f"✓ {success}/{total} files in /clipboard/{folder_name + '/' if folder_name else ''}")
    else:
        click.echo(f"{success} copied, {errors} failed")
        for rel, msg in failed_files:
            click.echo(f"  ✗ {rel}: {msg}", err=True)
    if folder_name:
        click.echo(f"  paperclip ls /clipboard/{folder_name}/")


@click.command(
    "mv",
    context_settings=dict(
        ignore_unknown_options=True,
        allow_extra_args=True,
        help_option_names=[],
    ),
)
@click.argument("args", nargs=-1, type=click.UNPROCESSED)
def mv_command(args: tuple):
    """Move or rename documents/folders within your clipboard.

    \b
    Clipboard paths are moved/renamed server-side (metadata only):
        paperclip mv /clipboard/my_papers /clipboard/archive/   → move/rename a folder
        paperclip mv /clipboard/a/usr_abc /clipboard/b/         → move a document
        paperclip mv /clipboard/a/usr_abc /clipboard/a/new.pdf  → rename a document
    A local filesystem path is uploaded instead (like cp):
        paperclip mv ./report.pdf /clipboard/analyses/
    """
    from pathlib import Path as _Path

    positionals = [a for a in args if not str(a).startswith("-")]
    source = positionals[0] if positionals else None

    # A local filesystem path (that exists) is uploaded; anything else
    # (/clipboard, corpus paths, usr_ IDs) is a server-side move/rename.
    local_path = None
    if source is not None:
        candidate = _Path(source).expanduser()
        if candidate.exists():
            local_path = str(candidate.resolve())

    if local_path is None:
        from .app import _execute_argv

        _execute_argv("mv", list(args))
        return

    dest = positionals[1] if len(positionals) > 1 else "/clipboard/"
    _cp_upload_local(local_path, dest)


@click.command("share")
@click.argument("folder_path")
@click.argument("email")
@click.option("--role", type=click.Choice(["viewer", "editor"]), default="viewer", help="Permission level")
def share_command(folder_path: str, email: str, role: str):
    """Share a clipboard folder with a user by email.

    \b
    Examples:
        paperclip share my_papers bob@company.com
        paperclip share my_papers bob@company.com --role editor
    """
    folder_path = folder_path.strip("/").replace("clipboard/", "").replace("/clipboard", "")
    if not folder_path:
        click.echo("Usage: paperclip share <folder> <email>", err=True)
        raise SystemExit(1)

    cfg_data = _load_config()
    base_url = cfg_data.get("base_url", "https://paperclip.gxl.ai")
    headers: dict = {}
    api_key = os.environ.get("PAPERCLIP_API_KEY", "")
    if api_key:
        headers["X-API-Key"] = api_key
    else:
        from ..client.credentials import Credentials
        creds = Credentials.load()
        if creds:
            headers["Authorization"] = f"Bearer {creds.get_id_token()}"
        else:
            click.echo("Not authenticated. Run: paperclip login", err=True)
            raise SystemExit(1)

    resp = requests.post(
        f"{base_url}/api/user/shares",
        headers={**headers, "Content-Type": "application/json"},
        json={"folder_path": folder_path, "email": email, "role": role},
        timeout=15,
    )

    if resp.status_code == 400:
        click.echo(f"Error: {resp.json().get('detail', 'Bad request')}", err=True)
        raise SystemExit(1)
    if not resp.ok:
        click.echo(f"Error: HTTP {resp.status_code}", err=True)
        raise SystemExit(1)

    data = resp.json()
    name = data.get("shared_with_name") or email
    click.echo(f"✓ Shared /clipboard/{folder_path}/ with {name} ({role})")


@click.command("unshare")
@click.argument("folder_path")
@click.argument("email")
def unshare_command(folder_path: str, email: str):
    """Remove a user's access to a shared folder.

    \b
    Examples:
        paperclip unshare my_papers bob@company.com
    """
    folder_path = folder_path.strip("/").replace("clipboard/", "").replace("/clipboard", "")
    if not folder_path:
        click.echo("Usage: paperclip unshare <folder> <email>", err=True)
        raise SystemExit(1)

    cfg_data = _load_config()
    base_url = cfg_data.get("base_url", "https://paperclip.gxl.ai")
    headers: dict = {}
    api_key = os.environ.get("PAPERCLIP_API_KEY", "")
    if api_key:
        headers["X-API-Key"] = api_key
    else:
        from ..client.credentials import Credentials
        creds = Credentials.load()
        if creds:
            headers["Authorization"] = f"Bearer {creds.get_id_token()}"
        else:
            click.echo("Not authenticated. Run: paperclip login", err=True)
            raise SystemExit(1)

    # List shares to find the one matching the email
    resp = requests.get(
        f"{base_url}/api/user/shares",
        headers=headers,
        params={"folder_path": folder_path},
        timeout=15,
    )
    if not resp.ok:
        click.echo(f"Error: HTTP {resp.status_code}", err=True)
        raise SystemExit(1)

    shares = resp.json()
    match = next((s for s in shares if s.get("shared_with_email", "").lower() == email.lower()), None)
    if not match:
        click.echo(f"No share found for {email} on /clipboard/{folder_path}/", err=True)
        raise SystemExit(1)

    # Revoke
    resp = requests.delete(
        f"{base_url}/api/user/shares/{match['id']}",
        headers=headers,
        timeout=15,
    )
    if not resp.ok:
        click.echo(f"Error: HTTP {resp.status_code}", err=True)
        raise SystemExit(1)

    click.echo(f"✓ Removed {email}'s access to /clipboard/{folder_path}/")